import test from 'node:test';import assert from 'node:assert/strict';import {createRun,generateScene,createBattle,stepBattle,settleBattle,applyReward,useMed,hit,aggroTarget,destinations,rollScene,random} from '../zr-engine.mjs';
test('seeded encounter replay is stable',()=>{function run(){const r=createRun(undefined,41),b=createBattle(r,generateScene('street',1,41));let frames=0;while(!b.done&&frames++<2000)stepBattle(b,.05);return {hp:b.allies.map(h=>h.hp),enemies:b.enemies.map(e=>e.hp),time:b.time,won:b.won};}assert.deepEqual(run(),run());});
test('wounds survive settlement and damage rewards; medkits are consumed',()=>{const r=createRun();const b=createBattle(r,generateScene('garden',0,4));b.allies[0].hp=21;b.won=true;r.q=1;settleBattle(r,b);assert.equal(r.party[0].hp,21);applyReward(r,'damage');assert.equal(r.party[0].hp,21);const n=r.supplies.med;useMed(r);assert.equal(r.party[0].hp,56);assert.equal(r.supplies.med,n-1);});
test('headshot kills once; shield and armor never create negative damage',()=>{const b=createBattle(createRun(),generateScene('street',0,2));const z=b.enemies[0],a=b.allies[0];z.shield=1000;hit(b,a,z,10);assert.equal(z.hp,z.maxHp);hit(b,a,z,100,'headshot');assert.equal(z.hp,0);hit(b,a,z,100,'headshot');assert.equal(b.events.filter(e=>e.type==='kill').length,1);});
test('school waves begin inactive then arrive; rear hero is not default target',()=>{const b=createBattle(createRun(['evan','rosa']),generateScene('street',2,3));assert.equal(b.enemies.filter(e=>e.active).length,4);assert.equal(aggroTarget(b.enemies[0],b.allies,0).id,'rosa');for(let i=0;i<110;i++)stepBattle(b,.05);assert.ok(b.enemies.filter(e=>e.active).length>=8);});
test('threat and taunt can change aggro, dead targets never retained',()=>{const b=createBattle(createRun(['evan','rosa']),generateScene('street',0,3));const z=b.enemies[0];z.threat.evan=1000;assert.equal(aggroTarget(z,b.allies,0).id,'evan');z.taunt='rosa';z.tauntUntil=4;assert.equal(aggroTarget(z,b.allies,1).id,'rosa');b.allies[1].hp=0;assert.equal(aggroTarget(z,b.allies,1).id,'evan');});
test('every offered route can reach the garage and home',()=>{function walk(r){if(r.q===5)return true;const dest=destinations(r);assert.ok(dest.length);return dest.every(c=>walk({...r,...c}));}assert.ok(walk(createRun()));});
test('combat-only scene rolls exclude safe scenes',()=>{const rng=random(55);for(let i=0;i<100;i++)assert.ok(!rollScene(rng,true).safe);});
test('garage repair consumes scrap without healing or dropping party',()=>{const r=createRun();r.phase='milestone';r.party[0].hp=30;r.supplies.scrap=3;assert.ok(applyReward(r,'car'));assert.equal(r.supplies.scrap,0);assert.equal(r.party[0].hp,30);assert.ok(r.car);});
test('five-stage run reaches home through garage with persistent state',()=>{const r=createRun(['evan','rosa','jules','mara','noor'],52);for(let stage=1;stage<=5;stage++){const dest=destinations(r).find(c=>c.r===0)||destinations(r)[0];Object.assign(r,dest);const b=createBattle(r,generateScene('street',0,52+stage));let n=0;while(!b.done&&n++<2000)stepBattle(b,.05);assert.ok(b.won);settleBattle(r,b);if(stage===3){assert.equal(r.phase,'milestone');assert.ok(applyReward(r,'car'));}else if(stage<5)applyReward(r,'armor');}assert.equal(r.phase,'won');assert.equal(r.q,5);assert.ok(r.car);assert.equal(r.history.length,5);});
test('changing stance changes reproducible combat outcomes',()=>{function fight(stance){const r=createRun(['evan','mara','jules'],17);r.stance=stance;const b=createBattle(r,generateScene('street',2,17));while(!b.done)stepBattle(b,.05);return b.allies.map(a=>a.hp);}assert.notDeepEqual(fight('guard'),fight('press'));});
